"""Application wiring and a minimal router (no web framework on purpose)."""
import datetime as _dt
import re

from hbonboard.api import handlers
from hbonboard.api.http import Request, Response
from hbonboard.config import DEFAULTS
from hbonboard.kyc.client import IdchkClient
from hbonboard.models import Conflict, NotFound, VendorError
from hbonboard.services.backlog import BacklogReport
from hbonboard.services.notify import Outbox
from hbonboard.services.signup import SignupService
from hbonboard.services.verification import VerificationService
from hbonboard.store.repository import MemberRepository
from hbonboard.util.cache import TTLCache

ROUTES = [
    ("POST", r"^/members$", handlers.register_member),
    ("GET", r"^/members$", handlers.list_members),
    ("GET", r"^/members/(?P<member_id>[^/]+)$", handlers.get_member),
    ("POST", r"^/kyc/run$", handlers.run_verification),
    ("GET", r"^/reports/kyc-backlog$", handlers.kyc_backlog),
    ("GET", r"^/outbox$", handlers.outbox),
]


class App:
    def __init__(self, settings, repo, services):
        self.settings = settings
        self.repo = repo
        self.services = services
        self._routes = [(m, re.compile(p), h) for m, p, h in ROUTES]

    def handle(self, request):
        for method, pattern, handler in self._routes:
            match = pattern.match(request.path)
            if match and method == request.method:
                try:
                    return handler(self, request, **match.groupdict())
                except NotFound as exc:
                    return Response.error(404, str(exc))
                except Conflict as exc:
                    return Response.error(409, str(exc))
                except VendorError as exc:
                    return Response.error(502, str(exc))
                except ValueError as exc:
                    return Response.error(400, str(exc))
        return Response.error(404, f"no route for {request.method} {request.path}")

    def get(self, path, query=None):
        return self.handle(Request("GET", path, dict(query or {}), None))

    def post(self, path, body=None, query=None):
        return self.handle(Request("POST", path, dict(query or {}), body))


def build_app(today=None, clock=None, **overrides):
    settings = DEFAULTS.with_overrides(**overrides)
    today = today or _dt.date.today()
    repo = MemberRepository()
    outbox = Outbox()
    backlog = BacklogReport(repo, settings, TTLCache(settings.report_cache_ttl, clock=clock))
    services = {
        "signup": SignupService(repo, settings, today),
        "backlog": backlog,
        "outbox": outbox,
        "verification": VerificationService(
            repo, IdchkClient(settings), settings, today,
            notifier=outbox, on_resolved=backlog.invalidate,
        ),
    }
    return App(settings, repo, services)
"""Endpoint handlers. Each takes (app, request, **path_params) and returns a Response."""
from hbonboard.api.http import Response, str_param
from hbonboard.util.phone import mask_phone


def register_member(app, request):
    member = app.services["signup"].register(request.body or {})
    app.services["backlog"].invalidate()
    return Response(201, member.to_dict(mask=mask_phone))


def get_member(app, request, member_id):
    return Response.ok(app.repo.get(member_id).to_dict(mask=mask_phone))


def list_members(app, request):
    status = str_param(app_query(request), "status")
    members = sorted(app.repo.all(), key=lambda m: m.member_id)
    if status:
        members = [m for m in members if m.status == status]
    return Response.ok({"items": [m.to_dict(mask=mask_phone) for m in members]})


def run_verification(app, request):
    return Response.ok(app.services["verification"].run())


def kyc_backlog(app, request):
    return Response.ok(app.services["backlog"].summary())


def outbox(app, request):
    member_id = str_param(app_query(request), "member")
    return Response.ok({"items": app.services["outbox"].messages(member_id)})


def app_query(request):
    return request.query or {}
"""Vendor verdict codes -> member status."""
from hbonboard.models import ACTIVE, KYC_DONE, REJECTED, REVIEW

# 1 = identity matched, 2 = identity did not match; anything else goes to a person
VERDICT_STATUS = {1: ACTIVE, 2: REJECTED}


def status_for(code):
    return VERDICT_STATUS.get(code, REVIEW)


def apply_verdict(member, code):
    member.verdict = code
    member.status = status_for(code)
    member.kyc_state = KYC_DONE
    member.history.append(member.status)
    return member
"""Turns members waiting for an identity check into vendor request lines."""
from hbonboard.models import KycRequest
from hbonboard.util.dates import compact
from hbonboard.util.text import vendor_name


def to_request(member):
    return KycRequest(
        ref=member.member_id,
        name=vendor_name(member.name),
        birth=compact(member.birth),
        phone=member.phone,
    )


def build_batch(members):
    """One line per member, in phone-number order (the vendor's matching key)."""
    seen, requests = set(), []
